import os # Bound linear algebra threads for independent correction tasks.
os.environ['OPENBLAS_NUM_THREADS']='1'; os.environ['OMP_NUM_THREADS']='1' # Avoid nested numerical oversubscription.
import json, time, argparse # Record actual numerical correction costs and model lineage.
import numpy as np # Compute exact nodal residuals and independent error norms.
from scipy.sparse import load_npz, diags # Read original physical matrices and apply symmetric scaling.
from scipy.sparse.linalg import splu, LinearOperator, gmres # Apply residual-controlled sparse numerical correction with an explicit full factorization.
from fem import * # Reuse stable experiment identifiers and evidence serialization.
def correct(family): # Test finite-element correction independently from raw neural predictions.
    selected=json.loads((RUN/f'selected_{family}.json').read_text()); folder=RUN/'training'/f"round_{selected['selected_round']}"/family; evaluation=json.loads((folder/'evaluation.json').read_text()); saved=np.load(folder/'predictions.npz'); representation=np.load(folder/'representation.npz'); basis=representation['basis']; rows=[] # Freeze validation-selected raw model and fixed test cases.
    for index,case in enumerate(evaluation['cases']): # Correct only held-out cases without feeding their labels back into learning.
        if case['split'] not in ['test','ood']: continue # Keep training and calibration out of independent cost comparison.
        directory=RUN/'cases'/case['id']; data=np.load(directory/'fields.npz'); K=load_npz(directory/'stiffness.npz'); free=data['free']; f=data['f'].ravel(); reference=data['u'].ravel(); raw=saved['predicted'][index]; k=K[free][:,free].tocsc(); force=f[free]; norm=max(np.linalg.norm(force),1e-12) # Restore full actual constrained physical problem.
        start=time.time(); reduced=basis.T@(K@basis); reduced_force=basis.T@f; coeff=np.linalg.solve(reduced,reduced_force); galerkin=basis@coeff; galerkin_seconds=time.time()-start # Solve a separate reduced physical baseline without crediting neural prediction.
        start=time.time(); scale=1/np.sqrt(np.maximum(k.diagonal(),1e-30)); scaling=diags(scale); a=(scaling@k@scaling).tocsc(); b=scale*force; ilu=splu(a); preconditioner=LinearOperator(a.shape,ilu.solve); setup=time.time()-start # Explicitly charge the full sparse LU factorization to every physical correction comparison.
        alternatives=[]; vectors={} # Preserve raw, reduced and fully corrected results separately.
        for name,initial in [('neural_warm',raw[free]),('zero_cold',np.zeros(len(free))),('galerkin_warm',galerkin[free])]: # Benchmark equal tolerance and preconditioner with different initial iterates.
            history=[]; started=time.time(); solution,info=gmres(a,b,x0=initial/scale,M=preconditioner,rtol=1e-8,atol=0.,restart=10,maxiter=3,callback=lambda value:history.append(float(value)),callback_type='pr_norm'); elapsed=time.time()-started # Use scaled solver tolerance tighter than unchanged 1e-7 physical residual gate and retain thirty-iteration cap.
            result=np.zeros(len(f)); result[free]=scale*solution; refinement=[]; refine_started=time.time() # Reconstruct physical degrees before independent residual refinement.
            for correction in range(5): # Bound direct residual corrections without modifying the original acceptance threshold.
                physical_residual=force-k@result[free]; measured=float(np.linalg.norm(physical_residual)/norm); refinement.append(measured) # Measure the original unscaled equilibrium norm.
                if measured<1e-8: break # Stop after an explicit physical criterion tighter than the registered acceptance gate.
                result[free]+=scale*ilu.solve(scale*physical_residual) # Apply a full-factorization residual correction with all numerical cost disclosed.
            elapsed+=time.time()-refine_started; residual=float(np.linalg.norm((K@result-f)[free])/norm); error=float(np.linalg.norm(result-reference)/max(np.linalg.norm(reference),1e-12)); vectors[name]=result # Independently compare final field with fixed full-FEM reference.
            alternatives.append({'method':name,'iterations':len(history),'gmres_info':int(info),'physical_refinement_history':refinement,'iteration_seconds':elapsed,'setup_seconds_shared':setup,'full_equilibrium_relative':residual,'relative_L2':error,'status':'PASS' if residual<1e-7 and error<1e-5 else 'FAIL','acceptance':'independently measured original physical residual and reference error after bounded full-LU correction; GMRES flag retained separately','residual_history':history}) # Qualify the actual corrected field while retaining incomplete GMRES stopping diagnostics.
        out=RUN/'correction'/family; out.mkdir(parents=True,exist_ok=True); np.savez_compressed(out/(case['id']+'.npz'),raw=raw,galerkin=galerkin,reference=reference,**vectors) # Save actual corrected nodal fields without replacing raw neural output.
        native=json.loads((directory/'receipt.json').read_text())['ccx']['seconds']; rows.append({'id':case['id'],'split':case['split'],'raw_neural_relative':case['relative_L2'],'raw_neural_residual':case['full_equilibrium_relative'],'galerkin_relative':float(np.linalg.norm(galerkin-reference)/max(np.linalg.norm(reference),1e-12)),'galerkin_residual':float(np.linalg.norm((K@galerkin-f)[free])/norm),'galerkin_seconds':galerkin_seconds,'native_ccx_seconds':native,'alternatives':alternatives}) # Record all accuracy and cost comparisons.
        write_json(out/'correction.json',{'family':family,'selected_round':selected['selected_round'],'cases':rows,'interpretation':'Corrected result includes a full sparse finite-element equilibrium solve; it is not a standalone neural operator prediction.'}); print(family,case['id'],[(r['method'],r['iterations'],r['status']) for r in alternatives],flush=True) # Checkpoint each independent case and report failures honestly.
if __name__=='__main__': # Run explicit family correction benchmark.
    parser=argparse.ArgumentParser(); parser.add_argument('--family',required=True,choices=FAMILIES); args=parser.parse_args(); correct(args.family) # Execute the fully audited numerical fallback.
